import { Fragment, type ReactNode, type CSSProperties } from "react";

const ICONS: Record<string, string> = {
  plan: '<path d="M9 3h6"/><path d="M10 3v6.5L5 19a1 1 0 0 0 .9 1.5h12.2A1 1 0 0 0 19 19l-5-9.5V3"/>',
  build: '<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/>',
  review: '<path d="m9 11 3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>',
  deploy: '<path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22" x2="12" y2="12"/>',
  default: '<circle cx="12" cy="12" r="9"/>',
};
function Ic({ n, size = 13 }: { n: string; size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"
      style={{ display: "inline-block", verticalAlign: "middle", flex: "0 0 auto" }}
      dangerouslySetInnerHTML={{ __html: ICONS[n] ?? ICONS.default }} />
  );
}
function Box({ children, as: As = "div", className, title, onClick, style }: { children?: ReactNode; as?: any; className?: string; title?: string; onClick?: () => void; style?: CSSProperties }) {
  return <As className={className} title={title} onClick={onClick} style={style}>{children}</As>;
}

export type RailStatus = "complete" | "ahead" | "active" | "skipped" | "locked" | "upcoming";
export interface RailNode {
  key: string;
  status: RailStatus;
  icon: string;
  title?: string;
  label?: string;
}
export type ConnectorKind = "solid" | "dim";
function nodeContent(n: RailNode): ReactNode {
  return n.status === "complete" || n.status === "ahead" ? "\u2713" : <Ic n={n.icon} size={13} />;
}
function defaultConnector(nodes: RailNode[], i: number): ConnectorKind {
  return nodes[i].status === "complete" ? "solid" : "dim";
}
const DEMO_NODES: RailNode[] = [
  { key: "plan", status: "complete", icon: "plan", title: "Plan", label: "Plan" },
  { key: "build", status: "active", icon: "build", title: "Build", label: "Build" },
  { key: "review", status: "upcoming", icon: "review", title: "Review", label: "Review" },
  { key: "deploy", status: "locked", icon: "deploy", title: "Deploy", label: "Deploy" },
];
export function ProgressionRail({
  nodes = DEMO_NODES,
  variant = "stepper",
  selectedIdx = 1,
  onSelect,
  highlight,
  connectorKind,
}: {
  nodes?: RailNode[];
  variant?: "compact" | "stepper";
  selectedIdx?: number;
  onSelect?: (i: number) => void;
  highlight?: Set<string>;
  connectorKind?: (nodes: RailNode[], i: number) => ConnectorKind;
}) {
  if (nodes.length === 0) return null;
  const conn = connectorKind ?? defaultConnector;
  const rail = (
    <Box className={`prail ${variant}`}>
      {nodes.map((n, i) => {
        const segClass =
          `prail-seg ${n.status}` +
          (i === selectedIdx ? " sel" : "") +
          ((highlight instanceof Set && highlight.has(n.key)) ? " attn" : "");
        const inner = (
          <>
            <Box as="span" className={`prail-node ${n.status}`}>{nodeContent(n)}</Box>
            {variant === "stepper" && <Box as="span" className="prail-label">{n.label}</Box>}
          </>
        );
        return (
          <Fragment key={n.key}>
            {onSelect ? (
              <button type="button" className={segClass} title={n.title ?? n.label} onClick={() => onSelect(i)}>
                {inner}
              </button>
            ) : (
              <Box as="span" className={segClass} title={n.title}>
                {inner}
              </Box>
            )}
            {i < nodes.length - 1 && <Box as="span" className={"prail-conn " + conn(nodes, i)} />}
          </Fragment>
        );
      })}
    </Box>
  );
  return variant === "stepper" ? <Box className="prail-wrap">{rail}</Box> : rail;
}

